// WsdlDefinition_STATUSGenerator returns a generator of WsdlDefinition_STATUS instances for property testing.
// We first initialize wsdlDefinition_STATUSGenerator with a simplified generator based on the
// fields with primitive types then replacing it with a more complex one that also handles complex fields
// to ensure any cycles in the object graph properly terminate.
func WsdlDefinition_STATUSGenerator() gopter.Gen {
	if wsdlDefinition_STATUSGenerator != nil {
		return wsdlDefinition_STATUSGenerator
	}

	generators := make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForWsdlDefinition_STATUS(generators)
	wsdlDefinition_STATUSGenerator = gen.Struct(reflect.TypeOf(WsdlDefinition_STATUS{}), generators)

	// The above call to gen.Struct() captures the map, so create a new one
	generators = make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForWsdlDefinition_STATUS(generators)
	AddRelatedPropertyGeneratorsForWsdlDefinition_STATUS(generators)
	wsdlDefinition_STATUSGenerator = gen.Struct(reflect.TypeOf(WsdlDefinition_STATUS{}), generators)

	return wsdlDefinition_STATUSGenerator
}

