	gens["ImportMethod"] = gen.PtrOf(gen.OneConstOf(WsdlImportMethod_STATUS_NotSpecified, WsdlImportMethod_STATUS_SoapPassThrough, WsdlImportMethod_STATUS_SoapToRest))
